#include <iostream>
#include <string>
#include <vector>

class Team {
    std::vector<std::string> members_;   // RAII 成员：自己管内存
public:
    void add(const std::string& s) { members_.push_back(s); }
    size_t size() const { return members_.size(); }
};                                       // 不写析构/拷贝/移动 —— 编译器合成版天然正确

int main() {
    Team t;
    t.add("ann");
    t.add("bob");
    Team u = t;          // 逐成员拷贝，vector 自身深拷贝，无双重释放风险
    u.add("cid");
    std::cout << u.size() << ' ' << t.size();
}
